"""Real audio for the backend tests: generated by FFmpeg, mixed by the real backend."""

from fractions import Fraction
from pathlib import Path

from media_house.core.application.ports import ProcessRunner
from media_house.core.domain import Rational
from media_house.core.infrastructure.process import SubprocessRunner
from media_house.modules.audio_mix_engine.application.ports import MixRequest, StemRequest
from media_house.modules.audio_mix_engine.domain.profile import Limiter
from media_house.modules.audio_mix_engine.domain.spec import MixBus, MixClip, RenderConfig
from media_house.modules.audio_mix_engine.domain.values import BusRole, Provenance
from media_house.modules.audio_mix_engine.infrastructure.ffmpeg_backend import FfmpegAudioBackend
from media_house.shared.concurrency import CancellationToken
from tests.support.media_factories import ffmpeg

RATE = 48000
CANCEL = CancellationToken()


def runner() -> ProcessRunner:
    return SubprocessRunner()


def backend() -> FfmpegAudioBackend:
    return FfmpegAudioBackend(runner())


def tone(
    path: Path, seconds: float, *, hz: int = 440, rate: int = RATE, volume: float = 1.0
) -> Path:
    ffmpeg(
        "-f", "lavfi", "-i", f"sine=frequency={hz}:duration={seconds}:sample_rate={rate}",
        "-af", f"volume={volume}", "-ac", "2", "-c:a", "pcm_s16le", str(path),
    )  # fmt: skip
    return path


def noise(path: Path, seconds: float, *, rate: int = RATE, amplitude: float = 0.1) -> Path:
    ffmpeg(
        "-f", "lavfi", "-i", f"anoisesrc=d={seconds}:c=pink:a={amplitude}:r={rate}",
        "-ac", "2", "-c:a", "pcm_s16le", str(path),
    )  # fmt: skip
    return path


def r(value: float | Fraction) -> Rational:
    f = Fraction(value).limit_denominator(100000)
    return Rational(f.numerator, f.denominator)


def clip(
    clip_id: str,
    source: str,
    start_s: float,
    length_s: float,
    *,
    src_in: float = 0.0,
    gain: float = 0.0,
    fade_in: float = 0.0,
    fade_out: float = 0.0,
    speed: float = 1.0,
    curve: str = "linear",
    pan: float = 0.0,
) -> MixClip:
    return MixClip(
        clip_id=clip_id,
        track_id="T",
        source_id=source,
        source_in=r(src_in),
        source_out=r(src_in + length_s * speed),
        start_sample=round(start_s * RATE),
        end_sample=round((start_s + length_s) * RATE),
        gain_db=gain,
        fade_in=r(fade_in),
        fade_out=r(fade_out),
        fade_curve=curve,
        speed=r(speed),
        channels="source",
        pan=pan,
        provenance=Provenance.COMPILED,
        origin_ref=clip_id,
    )


def bus(role: BusRole = BusRole.DIALOGUE, **kw: object) -> MixBus:
    return MixBus(role.value, role, role.value, "master", kw.pop("gain_db", 0.0), **kw)  # type: ignore[arg-type]


def stem(
    tmp: Path,
    clips: tuple[MixClip, ...],
    sources: dict[str, Path],
    *,
    seconds: float,
    bus_: MixBus | None = None,
    ducks: tuple[object, ...] = (),
    automation: tuple[object, ...] = (),
    rates: dict[str, int | None] | None = None,
    name: str = "stem.wav",
) -> Path:
    destination = tmp / name
    backend().render_stem(
        StemRequest(
            bus=bus_ or bus(),
            clips=clips,
            ducks=ducks,  # type: ignore[arg-type]
            automation=automation,  # type: ignore[arg-type]
            trims={},
            sources=sources,
            source_rates=rates or dict.fromkeys(sources, RATE),
            sample_rate=RATE,
            timebase_rate=RATE,
            duration_samples=round(seconds * RATE),
            destination=destination,
        ),
        CANCEL,
    )
    return destination


def mix(
    tmp: Path,
    stems: tuple[Path, ...],
    seconds: float,
    *,
    trim: float = 0.0,
    ceiling: float = -1.5,
    channels: int = 2,
    name: str = "mix.wav",
    master_gain: float = 0.0,
) -> Path:
    destination = tmp / name
    master = MixBus("master", BusRole.MASTER, "Master", None, master_gain, limiter=Limiter(ceiling))
    backend().render_mix(
        MixRequest(
            stems, master, trim, RenderConfig(RATE, 24, channels, "wav", "pcm_s24le"),
            round(seconds * RATE), destination,
        ),
        CANCEL,
    )  # fmt: skip
    return destination
